define([],function(){'use strict';var SR=window.SpeechRecognition||window.webkitSpeechRecognition,WARN_KEY='unics_voice_warned';function appendText(f,t){if(!t)return;if(f.isContentEditable){f.innerHTML+=(f.innerHTML?' ':'')+t;}else{var s=f.value&&!/\s$/.test(f.value)?' ':'';f.value+=s+t;}f.dispatchEvent(new Event('input',{bubbles:true}));f.dispatchEvent(new Event('change',{bubbles:true}));}function makeButton(f){var b=document.createElement('button');b.type='button';b.className='btn btn-outline-secondary btn-sm unics-voice-btn';b.innerHTML='<span aria-hidden="true">🎤</span> Диктовать';b.setAttribute('aria-label','Диктовать ответ голосом');var rec=null,listening=false;b.addEventListener('click',function(){try{if(!sessionStorage.getItem(WARN_KEY)){var ok=window.confirm('Голосовой ввод использует браузерное распознавание речи. В некоторых браузерах аудио обрабатывается на внешнем сервере. Продолжить?');if(!ok)return;sessionStorage.setItem(WARN_KEY,'1');}}catch(e){}if(listening&&rec){rec.stop();return;}rec=new SR();rec.lang='ru-RU';rec.interimResults=false;rec.continuous=false;rec.onstart=function(){listening=true;b.classList.add('btn-danger');b.classList.remove('btn-outline-secondary');b.innerHTML='<span aria-hidden="true">⏺</span> Слушаю...';};rec.onresult=function(ev){var t='';for(var i=ev.resultIndex;i<ev.results.length;i++){if(ev.results[i].isFinal)t+=ev.results[i][0].transcript;}appendText(f,t.trim());};rec.onerror=function(){};rec.onend=function(){listening=false;b.classList.remove('btn-danger');b.classList.add('btn-outline-secondary');b.innerHTML='<span aria-hidden="true">🎤</span> Диктовать';};try{rec.start();}catch(e){listening=false;}});return b;}function attach(){var fields=document.querySelectorAll('#region-main textarea, #region-main .editor_atto_content[contenteditable="true"]');fields.forEach(function(f){if(f.dataset.unicsVoice)return;if(f.tagName==='TEXTAREA'&&(f.classList.contains('d-none')||f.style.display==='none'))return;f.dataset.unicsVoice='1';var w=document.createElement('div');w.className='unics-voice-wrap mt-1 mb-2';w.appendChild(makeButton(f));f.parentNode.insertBefore(w,f.nextSibling);});}return{init:function(){if(!SR)return;if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){setTimeout(attach,800);});}else{setTimeout(attach,800);}}};});
